// Walk up the prototype chain to find the descriptor and the object
  // that owns it. This allows spying on methods/getters inherited from
  // any ancestor (not just the immediate prototype), and lets us
  // restore the property on the same object where it was originally
  // defined so that no own property is leaked onto `obj` after restore.
  let descriptorOwner: any = obj
  let objDescriptor = getDescriptor(obj, accessName)
  let protoDescriptor: PropertyDescriptor | undefined
  if (!objDescriptor) {
    let proto: any = Object.getPrototypeOf(obj)
    while (proto && !protoDescriptor) {
      protoDescriptor = getDescriptor(proto, accessName)
      if (protoDescriptor) {
        descriptorOwner = proto
        break
      }
      proto = Object.getPrototypeOf(proto)
    }
  }
  let originalDescriptor = objDescriptor || protoDescriptor

  assert(
    originalDescriptor || accessName in obj,
    `${String(accessName)} does not exist`
  )

  let ssr = false

  // vite ssr support - actual function is stored inside a getter
  if (
    accessType === 'value' &&
    originalDescriptor &&
    !originalDescriptor.value &&
    originalDescriptor.get
  ) {
    accessType = 'get'
    ssr = true
    mock = originalDescriptor.get!()
  }

  let original: Procedure | undefined

  if (originalDescriptor) {
    original = originalDescriptor[accessType]
  } else if (accessType !== 'value') {
    original = () => obj[accessName as keyof T]
  } else {
    original = obj[accessName as keyof T] as unknown as Procedure
  }

  if (original && isSpyFunction(original)) {
    original = original[SYMBOL_STATE].getOriginal()
  }

  let reassign = (cb: any) => {
    // Build the new descriptor based on the original one (if found) so
    // that sibling accessors such as the setter are preserved when we
    // spy on a getter (and vice versa).
    let desc: any = originalDescriptor
      ? { ...originalDescriptor }
      : { configurable: true, writable: true }
    delete desc.value
    if (accessType !== 'value') {
      delete desc.writable // getter/setter can't have writable attribute at all
    }
    desc[accessType] = cb
    define(descriptorOwner, accessName, desc)
  }
  let restore = () =>
    originalDescriptor && !original
      ? define(descriptorOwner, accessName, originalDescriptor)
      : reassign(original)

